INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16601, 'Isaiah 3:3', 'Isaiah', 3, 3, '&nbsp;فوجى آفسران، معتبر کسان، مشيران، ماهر کاريګران او جادوګران واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16602, 'Isaiah 3:4', 'Isaiah', 3, 4, '&nbsp;زۀ به هلکان د هغوئ مشران جوړ کړم، او ماشومان به په هغوئ حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16603, 'Isaiah 3:5', 'Isaiah', 3, 5, '&nbsp;خلق به يو بل سره زياتے کوى. هر يو سړے به په بل سړى او هر يو ګاونډى به په بل ګاونډى رُعب اچوى. ځوانان به د خپلو مشرانو بې‌عزتى کوى او بدکرداره خلق به د عزتمندو بې‌عزتى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16604, 'Isaiah 3:6', 'Isaiah', 3, 6, '&nbsp;په هغه وخت کښې به يو کس خپل ورور ته ووائى، ”تر اوسه پورې تا سره څادر شته نو په دې وجه راشه او زمونږ مشر جوړ شه. او د کنډراتو د دې ډيرى ذمه وارى اوچته کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16605, 'Isaiah 3:7', 'Isaiah', 3, 7, '&nbsp;خو هغه به ورته په جواب کښې وائى، ”نه، زۀ ستاسو علاج نۀ شم کولے. نۀ ما سره خوراک شته او نۀ ما څادر شته. ما د عوامو مشر مۀ جوړَوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16606, 'Isaiah 3:8', 'Isaiah', 3, 8, '&nbsp;بې‌شکه چې يروشلم په لړزان دے. او په يهوداه زوال راغلے دے. هغوئ چې هر څۀ وائى او کوم عمل کوى هغه د مالِک خُدائ خِلاف دے، هغوئ په جار بار د مالِک خُدائ خلاف بغاوت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16607, 'Isaiah 3:9', 'Isaiah', 3, 9, '&nbsp;د هغوئ مخونو نه د هغوئ ملامتيا څرګنده ده. هغوئ د سدوم د خلقو په شان په جار بار ګناه کړې ده. په هغوئ افسوس. هغوئ په خپله تباهى په ځان باندې راوستلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16608, 'Isaiah 3:10', 'Isaiah', 3, 10, '&nbsp;صادقانو له خوشخبرى ورکړه چې هغوئ بختور دى، ځکه چې هغوئ به د خپلو اعمالو د ښې مېوې نه خوند واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16609, 'Isaiah 3:11', 'Isaiah', 3, 11, '&nbsp;خو بدعمله خلق تباه دى، هغوئ چې د نورو خلقو سره څۀ سلوک کړے وى نو هم هغه شان عمل به د هغوئ سره هم وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16610, 'Isaiah 3:12', 'Isaiah', 3, 12, '&nbsp;ځوانان زما د خلقو سره زياتے کوى، او ښځې په هغوئ باندې حکومت کوى. اے زما خلقو، خپلو مشرانو تاسو په غلطه لار باندې روان کړى يئ، او هغوئ ستاسو لارې ستاسو نه ګډې وډې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16611, 'Isaiah 3:13', 'Isaiah', 3, 13, '&nbsp;مالِک خُدائ په خپل عدالت کښې تيار دے، او د خلقو د عدالت دپاره ولاړ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16612, 'Isaiah 3:14', 'Isaiah', 3, 14, '&nbsp;مالِک خُدائ د خپلو خلقو آفسران او مشران راولى چې د هغوئ عدالت وکړى. د هغوئ خِلاف د مالِک خُدائ دا اِعتراض دے، ”تاسو زما د انګورو باغ تباه کړے دے او د غريبانانو نه لوټ کړے شوے مال ستاسو په کورونو کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16613, 'Isaiah 3:15', 'Isaiah', 3, 15, '&nbsp;تاسو دا حق نۀ لرئ چې زما خلقو له رګړه ورکړئ او د غريبانانو پوزې زمکې پورې راکاږئ. ما مالِک خُدائ، ربُ الافواج دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16614, 'Isaiah 3:16', 'Isaiah', 3, 16, '&nbsp;مالِک خُدائ فرمائى، ”ګورئ، د يروشلم ښځې څومره مغروره دى. هغوئ هسکه غاړه نيولې وى او روانې وى. هغوئ تل نخرې کوى. هغوئ د نازونو او نخرو قدمونه اخلى او پانزېبونه شړنګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16615, 'Isaiah 3:17', 'Isaiah', 3, 17, '&nbsp;زۀ به د هغوئ په سرونو باندې دانې راوخېژوم او ګنجۍ به يې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16616, 'Isaiah 3:18', 'Isaiah', 3, 18, '&nbsp;داسې ورځ راروانه ده چې مالِک خُدائ به د يروشلم د ښځو نه هغه هر څۀ واخلى په څۀ چې هغوئ ځانونه ښائسته کوى، پانزېبونه، هارونه، د سپوږمۍ په شان کالے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16617, 'Isaiah 3:19', 'Isaiah', 3, 19, '&nbsp;والۍ، بنګړى، نقابونه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16618, 'Isaiah 3:20', 'Isaiah', 3, 20, '&nbsp;لوپټې، ګونګړوګان، کمربندې، د عطرو بوتلې، تعويذونه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16619, 'Isaiah 3:21', 'Isaiah', 3, 21, '&nbsp;ګوتمې، نتکۍ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16620, 'Isaiah 3:22', 'Isaiah', 3, 22, '&nbsp;ښائسته جامې، چُوغې، شالونه، پرسونه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16621, 'Isaiah 3:23', 'Isaiah', 3, 23, '&nbsp;شيشې، د کتان جامې، پړُونى او بُرقعې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16622, 'Isaiah 3:24', 'Isaiah', 3, 24, '&nbsp;د عطرو د خوشبو په ځائ به د هغوئ نه بدبوئ خېژى، د کمربند په ځائ به هغوئ د ځان نه پړى تاو کړى وى، د ښائسته زلفو لرلو په ځائ به هغوئ ګنجۍ شى، د قيمتى جامو په ځائ به هغوئ د ټاټ جامې اغوستې وى. د هغوئ حُسن به په شرم بدل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16623, 'Isaiah 3:25', 'Isaiah', 3, 25, '&nbsp;د ښار سړى به په تُوره وژلے شى، ستاسو تکړه سړى او سپاهيان به په جنګ کښې مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16624, 'Isaiah 3:26', 'Isaiah', 3, 26, '&nbsp;د ښار دروازې به ژړا او ماتم کوى او ښار به په خپله د هغه ښځې په شان وى چې يواځې پاتې شى او په زمکه کښېنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16625, 'Isaiah 4:1', 'Isaiah', 4, 1, '&nbsp;کله چې هغه وخت راشى، نو اووۀ ښځې به يو سړے راونيسى او ورته به ووائى، ”مونږ به په خپله د خپل ځان دپاره د جامو او روټۍ اِنتظام کوُو، خو چې مونږ صرف ستا په نوم پورې تړلې يُو چې تۀ زمونږ خاوند يې، او داسې به مونږ د شرم نه بچ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16626, 'Isaiah 4:2', 'Isaiah', 4, 2, '&nbsp;هغه وخت راروان دے چې د مالِک خُدائ څانګه به د هغه مُلک هر يو بوټے او ونه لويه او ښائسته کړى. نو چې کوم اِسرائيليان ژوندى پاتې وى نو هغوئ ټول به خوشحاله وى او په هغه فصلونو به فخر کوى چې په هغه مُلک کښې پېدا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16627, 'Isaiah 4:3', 'Isaiah', 4, 3, '&nbsp;هر څوک چې په يروشلم کښې پاتې وى، نو خُدائ پاک به د هغۀ دپاره ژوند غوره کړے وى نو هغه به مقدس ګڼلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16628, 'Isaiah 4:4', 'Isaiah', 4, 4, '&nbsp;مالِک خُدائ به د صيون ښار د ښځې ګندګى ووينځى، هغه به د يروشلم نه د وينې داغونه د عدالت روح سره او د اور روح سره صفا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16629, 'Isaiah 4:5', 'Isaiah', 4, 5, '&nbsp;بيا د صيون په غرۀ او په هغه ټولو خلقو چې هلته راغونډ وى، په هغوئ به مالِک خُدائ د ورځې وريځ راولېږى او د شپې به ورباندې لوګے او ځلېدونکے اور راولېږى. د خُدائ پاک جلال به هغه ټول ښار پټ کړى او د هغې حِفاظت به وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16630, 'Isaiah 4:6', 'Isaiah', 4, 6, '&nbsp;د هغۀ جلال به په هغه ښار باندې لکه د خېمې په شان وى چې د ورځې د ګرمۍ نه سورے جوړ کړى او دا به د امن ځائ وګرځوى او د باران او طوفان نه به يې محفوظ وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16631, 'Isaiah 5:1', 'Isaiah', 5, 1, '&nbsp;راځئ چې زۀ د خپل محبوب دپاره سندره وايم، دا زما د دوست او د هغۀ د انګورو د باغ سندره ده. زما د دوست د انګورو يو باغ وو، چې دا باغ په يوه زرخېزه غونډۍ باندې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16632, 'Isaiah 5:2', 'Isaiah', 5, 2, '&nbsp;هغۀ زمکه وکنستله او د هغې نه يې کاڼى صفا کړل، هغۀ د بهترينو انګورو بوټى وکَرل. او د دې باغ په مينځ کښې يې د حِفاظت دپاره د څوکيدارۍ يو برج جوړ کړو، هغۀ د انګورو نه د رس ويستلو دپاره د کاڼى نه لنګرۍ جوړه کړه. هغۀ د ښو انګورو د پخېدو انتظار وکړو، خو چې کله انګور پاخۀ شول نو هغه ټول تراوۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16633, 'Isaiah 5:3', 'Isaiah', 5, 3, '&nbsp;نو اوس، اے د يروشلم او د يهوداه اوسېدونکو خلقو، زما او زما د انګورو د باغ په مينځ کښې فېصله وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16634, 'Isaiah 5:4', 'Isaiah', 5, 4, '&nbsp;داسې څۀ شته چې ما د دې باغ دپاره نۀ وى کړى؟ نو بيا چې ما د دې باغ نه د خوږو انګورو توقع ساتله، نو دې تراوۀ ولې ونيول؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16635, 'Isaiah 5:5', 'Isaiah', 5, 5, '&nbsp;نو زۀ به اوس تاسو ته ووايم، چې زۀ به د دې خپل باغ سره څۀ کوم. د دې نه ګېرچاپېره چې کوم باړ دے هغه به ترې نه اخوا کړم، د دې د حِفاظت دېوالونه به راوغورزوم او ځناور به ورپرېږدم چې وې خورى او د پښو لاندې يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16636, 'Isaiah 5:6', 'Isaiah', 5, 6, '&nbsp;زۀ به د هغې زمکه شاړه کړم. نۀ به يې په بوټو کښې قينچى کيږى او نۀ به ورته ګوډ کيږى، هلته به ازغى او مرکونډۍ زرغونې شى. زۀ به وريځې هم منع کړم چې په دې باندې باران نۀ ورَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16637, 'Isaiah 5:7', 'Isaiah', 5, 7, '&nbsp;د اِسرائيل قوم د مالِک خُدائ ربُ الافواج د انګورو باغ دے، او د يهوداه خلق د انګورو هغه بوټى دى چې هغۀ په خوشحالۍ کَرلى دى. د هغۀ د دوئ نه طمع وه چې اِنصاف به کوى، خو په ځائ د دې هغوئ ظلمونه کول. هغۀ ترې نه د صداقت طمع لرله، خو په ځائ د دې هغۀ د ژړا چغې واورېدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16638, 'Isaiah 5:8', 'Isaiah', 5, 8, '&nbsp;په تاسو افسوس، تاسو نور نور کورونه او پټى اخلئ. خو په آخر کښې به د نورو خلقو دپاره ځائ پاتې نۀ شى او صرف تاسو به په هغه مُلک کښې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16639, 'Isaiah 5:9', 'Isaiah', 5, 9, '&nbsp;ما اورېدلى دى چې مالِک خُدائ ربُ الافواج قسم خوړلے دے چې، ”يقيناً چې د ډېرو کورونو نه به کنډرې جوړې شى، او په دې غټو او ښائسته کورونو کښې به هيڅوک نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16640, 'Isaiah 5:10', 'Isaiah', 5, 10, '&nbsp;په شل جربه زمکه باندې چې کوم د انګور باغ کَرلے شوے وى نو هغه به صرف دوويشت ليټره مے پېدا کوى. يو سل او شپېتۀ کلو تخم به صرف شپاړس کلو غله پېدا کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16641, 'Isaiah 5:11', 'Isaiah', 5, 11, '&nbsp;په تاسو افسوس څوک چې سحر وختى پاڅئ او په شرابو څښلو باندې شروع وکړئ او په ماښام کښې تر ناوخته پورې مے څښئ او ځانونه نشه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16642, 'Isaiah 5:12', 'Isaiah', 5, 12, '&nbsp;ستاسو په محفلونو کښې تاسو سره رباب، بينجو، تمبلونه، شپېلۍ او مے وى. دا خو ستاسو په خيال کښې هم نۀ راځى چې مالِک خُدائ څۀ کوى. او څۀ چې هغه کوى نو تاسو د هغې لحاظ نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16643, 'Isaiah 5:13', 'Isaiah', 5, 13, '&nbsp;نو ځکه زما قوم به د خپلې ناپوهۍ له وجې جلاوطن کړے شى. ستاسو مشران به د لوږې نه مړۀ شى او ستاسو عوام به د تندې نه مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16644, 'Isaiah 5:14', 'Isaiah', 5, 14, '&nbsp;تورو خاورو هغوئ ته خپله خولۀ کولاو نيولې ده دپاره د دې چې د يروشلم غټ خلق او عوام، مست او شور جوړونکى خلق به ژوندى تېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16645, 'Isaiah 5:15', 'Isaiah', 5, 15, '&nbsp;هر يو کس به سپک کړے شى او څوک چې مغرور وى نو هغوئ ټول به عاجزان کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16646, 'Isaiah 5:16', 'Isaiah', 5, 16, '&nbsp;خو مالِک خُدائ ربُ الافواج د خپلې لويئ اظهار د هغه کار په کولو سره کوى چې کوم د اِنصاف وى او د خُدائ پاک راستى به د هغۀ د پاکوالى څرګندونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16647, 'Isaiah 5:17', 'Isaiah', 5, 17, '&nbsp;د ښار په کنډرو کښې به ګډُورى واښۀ خورى او د چېلو بچو ته به په کښې د څرن زمکه ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16648, 'Isaiah 5:18', 'Isaiah', 5, 18, '&nbsp;په تاسو افسوس څوک چې د شګى مزى پورې خپل ګناهونه راکاږئ، او څوک چې د غوَيانو د ګاډۍ په شان خپله بدعملې ځان پسې راکاږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16649, 'Isaiah 5:19', 'Isaiah', 5, 19, '&nbsp;تاسو وايئ، ”مالِک خُدائ دې زر زر خپل کار وکړى چې مونږ دا وګورو. او چې د بنى اِسرائيلو مقدس ذات کومه منصوبه جوړه کړې ده هغه دې زر سر ته ورسوى چې مونږ ته د هغې پته ولګى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16650, 'Isaiah 5:20', 'Isaiah', 5, 20, '&nbsp;په تاسو افسوس دے. تاسو بدو ته ښۀ وايئ او ښو ته بد وايئ. تاسو تيارۀ نه رڼا جوړَوئ او د رڼا نه تيارۀ جوړَوئ. کوم څيز چې تريخ وى نو د هغې نه خوږ جوړَوئ او چې کوم خوږ وى نو د هغې نه تريخ جوړَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16651, 'Isaiah 5:21', 'Isaiah', 5, 21, '&nbsp;په تاسو افسوس دے. ستاسو خيال دا وى چې تاسو عقلمند يئ او خپل ځان ډېر زيات هوښيار ګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16652, 'Isaiah 5:22', 'Isaiah', 5, 22, '&nbsp;په تاسو افسوس دے. د ميو په څښلو کښې خو تاسو ډېر تکړه يئ. او د شرابو په ګډولو کښې تاسو ښۀ ځوانى ښايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16653, 'Isaiah 5:23', 'Isaiah', 5, 23, '&nbsp;خو د رشوت په وجه تاسو مجرمان آزادوئ او د بې‌ګناه خلقو حقُونه خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16654, 'Isaiah 5:24', 'Isaiah', 5, 24, '&nbsp;نو اوس، لکه څنګه چې خسڼى او اوچ واښۀ ټسيږى او په اور کښې ايرې کيږى، نو داسې ستاسو جرړې به ورَستې شى او ستاسو غوټۍ به اوچې شى او هوا به يې يوسى. دا ځکه چې تاسو د مالِک خُدائ د ربُ الافواج شريعت رد کړے دے، او د بنى اِسرائيلو د مقدس ذات حکم ته مو سپک کتلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16655, 'Isaiah 5:25', 'Isaiah', 5, 25, '&nbsp;نو ځکه مالِک خُدائ خپلو خلقو ته سخت په قهر دے او خپل لاس يې اوچت کړے دے چې هغوئ له سزا ورکړى. غرونه به وخوځيږى او چې څوک مړۀ شى نو د هغوئ لاشونه به په کوڅو کښې د ګند په شان پاتې شى. خو د مالِک خُدائ غصه به بيا هم نۀ وى سړه شوې او هغۀ به د سزا دپاره لاس اوچت کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16656, 'Isaiah 5:26', 'Isaiah', 5, 26, '&nbsp;هغه به يو لرې قوم ته د راغوښتلو دپاره اِشاره وکړى. هغه هغوئ ته شپيلے ووهى چې د دُنيا د لرې سر نه راشى. او هغوئ زر زر او په منډه منډه راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16657, 'Isaiah 5:27', 'Isaiah', 5, 27, '&nbsp;د هغوئ يو کس به هم نۀ ستړے کيږى، او نۀ به تيندکونه خورى. نۀ به هغوئ د خوب دپاره ودريږى او نۀ د آرام دپاره. نۀ به هغوئ ملابند سپړى او نۀ به هغوئ د خپل پېزار تسمې پرانيزى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16658, 'Isaiah 5:28', 'Isaiah', 5, 28, '&nbsp;د هغوئ غشى به تېرۀ وى او د هغوئ ليندې به د ويشتلو دپاره تيارې وى. د هغوئ د آسونو د نالونو نه به بڅرکى الوځى او د هغوئ د جنګى ګاډو پايې به د هوا په شان تاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16659, 'Isaiah 5:29', 'Isaiah', 5, 29, '&nbsp;هغوئ د ازمرو په شان غړمبيږى، د داسې ازمرو په شان غړمبيږى چې ښۀ په ځوانى کښې وى. هغوئ غړمبار سره خپل ښکار راونيسى او يو خوا ته يې وړى او هيڅ څوک هم نۀ وى چې يې ترېنه خلاص کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16660, 'Isaiah 5:30', 'Isaiah', 5, 30, '&nbsp;په دغه ورځ به هغوئ په خپل دشمن باندې وغړمبيږى داسې لکه چې د سمندر چپې شور کوى. کۀ څوک هغه مُلک ته وګورى نو صرف تيارې او مصيبتونه به ورته ښکارى. او د وريځې د خورېدو په وجه به رڼا په تيارې بدله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16661, 'Isaiah 6:1', 'Isaiah', 6, 1, '&nbsp;په کوم کال چې عُزياه بادشاه مړ شو، نو ما مالِک خُدائ وليدو چې په اوچت او د لوئې مرتبې په تخت ناست وو. او د هغۀ د چُوغې لمن سره د هغۀ کور ډک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16662, 'Isaiah 6:2', 'Isaiah', 6, 2, '&nbsp;د هغۀ نه ګېرچاپېره بلېدونکے مخلوق ولاړ وو او د هر يو شپږ شپږ وزر وُو. دې هر يو خپل مخ په دوو وزرو باندې پټ کړے وو، په دوو وزرو باندې يې پښې پټې کړې وې او د دوو وزرو نه يې د الوتلو کار اخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16663, 'Isaiah 6:3', 'Isaiah', 6, 3, '&nbsp;هغوئ يو بل ته نعرې وهلې، ”مقدس، مقدس. مالِک خُدائ ربُ الافواج مقدس دے. د هغۀ د جلال نه دُنيا ډکه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16664, 'Isaiah 6:4', 'Isaiah', 6, 4, '&nbsp;د هغوئ د آوازونو شور د خُدائ پاک د کور چوکاټونه ولړزول او د مالِک خُدائ کور د لوږى نه ډک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16665, 'Isaiah 6:5', 'Isaiah', 6, 5, '&nbsp;نو ما ووئيل، ”په ما افسوس، زۀ تباه شوم، ځکه چې زما شونډې په ګناه ککړې دى، او د کومو خلقو سره چې زۀ اوسېږم د هغوئ شونډې هم ګنده دى. خو بيا هم ما په خپلو سترګو هغه بادشاه ليدلے دے چې هغه مالِک خُدائ ربُ الافواج دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16666, 'Isaiah 6:6', 'Isaiah', 6, 6, '&nbsp;نو بيا د هغه بلېدونکى مخلوق نه يو زما طرف ته راوالوتلو. هغۀ يوه بَله سکروټه راروانه کړې وه، هغۀ دا د قربان‌ګاه نه د يوې چمټې سره راخستې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16667, 'Isaiah 6:7', 'Isaiah', 6, 7, '&nbsp;هغۀ زما شونډو له بَله سکروټه وروړله او وې فرمائيل، ”دا سکروټه ستا د شونډو سره لګېدلې ده، نو په دې وجه ستا قصور ختم شو او ستا ګناهونه معاف شول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16668, 'Isaiah 6:8', 'Isaiah', 6, 8, '&nbsp;بيا ما د مالِک خُدائ آواز واورېدو چې وې فرمائيل، ”زۀ څوک ولېږم؟ زمونږ د طرف نۀ به څوک ځى؟“ نو ما ورته په جواب کښې ووئيل، ”زۀ حاضر يم. ما ولېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16669, 'Isaiah 6:9', 'Isaiah', 6, 9, '&nbsp;نو هغۀ ما ته وفرمائيل چې، ”لاړ شه او دې قوم ته دا پېغام ورسوه، ”هر څومره کۀ تاسو واورئ خو تاسو به پرې پوهه نۀ شئ، هر څومره کۀ ورته ګورئ نو تاسو به پرې پوهېږئ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16670, 'Isaiah 6:10', 'Isaiah', 6, 10, '&nbsp;د هغوئ زړونه سخت کړه، د هغوئ غوږونه کاڼۀ کړه او د هغوئ سترګې ړندې کړه، داسې نۀ وى چې هغوئ په خپلو سترګو وګورى او په خپلو غوږُونو واورى او خپلو زړونو کښې پوهه شى او زما طرف ته شفا دپاره راتاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16671, 'Isaiah 6:11', 'Isaiah', 6, 11, '&nbsp;ما ترې نه تپوس وکړو، ”اے مالِکه خُدايه، دا به تر کومې پورې وى؟“ هغۀ راته وفرمائيل، ”دا به تر هغې پورې وى چې ښارونه يې تباه او خوشى شى او چې د کورونو نه يې خلق ختم شى او زمکه يې شاړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16672, 'Isaiah 6:12', 'Isaiah', 6, 12, '&nbsp;تر هغې چې مالِک خُدائ هغوئ تر لرې لرې پورې وزغلوى او ټول مُلک يې خوشے پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16673, 'Isaiah 6:13', 'Isaiah', 6, 13, '&nbsp;کۀ په هغه مُلک کښې صرف لسمه حِصه خلق هم پاتې وى، نو هغه به بيا وسوزولے شى. هغه به د څېړۍ د ونې په شان داسې کټ شى چې صرف مونډ يې باقى پاتې شى.“ دا مونډ به يو مقدس تخم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16674, 'Isaiah 7:1', 'Isaiah', 7, 1, '&nbsp;کله چې د عُزياه نمسى او د يوتام زوئ احاز بادشاه په يهوداه باندې بادشاهى کوله، نو د شام بادشاه رضين او د اِسرائيل بادشاه د رملياه زوئ فقح په يروشلم باندې حمله وکړه، خو هغوئ د دې ښار قبضه کولو کښې ناکامه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16675, 'Isaiah 7:2', 'Isaiah', 7, 2, '&nbsp;کله چې دا خبر د يهوداه بادشاه ته ورسېدو چې د شام فوجيان اِسرائيل سره په جنګ کښې ملګرى شوى دى، نو هغه او د هغۀ ټول خلق دومره زيات ويرېدل او داسې ولړزېدل لکه چې په طوفان کښې ونې خوځيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16676, 'Isaiah 7:3', 'Isaiah', 7, 3, '&nbsp;نو مالِک خُدائ يشعياه ته وفرمائيل، ”خپل زوئ شياريشوب ځان سره روان کړه او احاز بادشاه سره مِلاوېدو له لاړ شه. تۀ به هغۀ سره په هغه سړک باندې مِلاو شې چرته چې دهوبيان جامې وينځى او د هغه نِهر لاندې سر سره په کوم چې د تالاب نه اوبۀ راکوزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16677, 'Isaiah 7:4', 'Isaiah', 7, 4, '&nbsp;هغۀ ته ووايه چې، ويښ اوسه او په قلار شه او نۀ چې ويريږى او نۀ پرېشانه شى. د رضين بادشاه، شاميانو او د رملياه د زوئ غصه د اور د هغه دوو لرګو په شان هيڅ هم نۀ ده چې په مړ کېدو بدل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16678, 'Isaiah 7:5', 'Isaiah', 7, 5, '&nbsp;شام، سره اِسرائيل او د رملياه زوئ ستا خِلاف منصوبه جوړه کړې ده، او وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16679, 'Isaiah 7:6', 'Isaiah', 7, 6, '&nbsp;راځئ چې مونږ په يهوداه باندې حمله وکړُو، خلق ويروو او قبضه يې کړُو، او بيا به د طابئيل زوئ په تخت باندې کښېنوو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16680, 'Isaiah 7:7', 'Isaiah', 7, 7, '&nbsp;خو مالِک خُدائ فرمائى چې، د هغوئ منصوبه به ناکامه شى. او دا به نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16681, 'Isaiah 7:8', 'Isaiah', 7, 8, '&nbsp;ولې چې د شام مشر دمشق دے او د دمشق مشر صرف رضين دے. او ترڅو چې د اِسرائيلو خبره ده، نو هغه به په پينځو شپېتو کالو کښې ټوټې ټوټې او په مکمل طور تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16682, 'Isaiah 7:9', 'Isaiah', 7, 9, '&nbsp;د اِسرائيل مشر سامريه دے او د سامريه مشر د رملياه زوئ دے. کۀ په ايمان قائم پاتې نۀ شوئ، نو يقيناً چې پخپله به قائم پاتې نۀ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16683, 'Isaiah 7:10', 'Isaiah', 7, 10, '&nbsp;مالِک خُدائ احاز له يو بل پېغام ولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16684, 'Isaiah 7:11', 'Isaiah', 7, 11, '&nbsp;”د مالِک خُدائ د خپل خُدائ پاک نه وغواړه چې يوه نښه درته وښائى. کۀ هغه د آسمان نه پاس وى او کۀ د عالمِ ارواح نه لاندې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16685, 'Isaiah 7:12', 'Isaiah', 7, 12, '&nbsp;خو احاز ورته اِنکار وکړو او وئيل يې چې، ”نه، نۀ به زۀ نښه غواړم او نۀ به مالِک خُدائ آزمائيم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16686, 'Isaiah 7:13', 'Isaiah', 7, 13, '&nbsp;نو په دې خبره يشعياه ورته وفرمائيل، ”اے د داؤد بادشاه اولاده، په کولاو غوږونو واورئ. ولې دا کافى نۀ ده چې تاسو د انسان صبر تمام کړئ؟ اوس تاسو زما د خُدائ پاک صبر هم تمامول غواړئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16687, 'Isaiah 7:14', 'Isaiah', 7, 14, '&nbsp;ښه نو بيا ګورئ، مالِک خُدائ به په خپله تاسو ته يوه نښه وښائى. يوه پېغله به اُميدواره شى او چې زوئ يې پېدا شى نو ”عمانو‌ايل“ يعنې، ”خُدائ زمونږ مل دے“ نوم به پرې کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16688, 'Isaiah 7:15', 'Isaiah', 7, 15, '&nbsp;په هغه وخت کښې چې کله هغه دومره شى چې ملائى او شات خوړے شى نو د خپل ښۀ او بد فېصله به په خپله کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16689, 'Isaiah 7:16', 'Isaiah', 7, 16, '&nbsp;هغه وخت به لا راغلے هم نۀ وى چې هغه د خپل ښۀ او بد فېصله پخپله کوى، نو د هغه دوو بادشاهانو مُلکونه به خوشى او برباد شى کوم چې تاسو يروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16690, 'Isaiah 7:17', 'Isaiah', 7, 17, '&nbsp;نو مالِک خُدائ به په تا، ستا په خلقو او په ټول شاهى خاندان داسې سخت وخت راولى چې د کله نه اِسرائيل د يهوداه نه جدا شوے دے نو تر نن ورځې پورې نۀ دے راغلے. هغه به د اسور بادشاه راولى چې په تاسو باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16691, 'Isaiah 7:18', 'Isaiah', 7, 18, '&nbsp;کله چې هغه وخت راشى، نو مالِک خُدائ به د مِصريانو د راغوښتو دپاره شپېلۍ ووهى چې د نيل درياب د لرې غاړو نه د مچانو په شان راشى او اسوريانو ته به شپېلۍ ووهى چې د شاتو د مچو په شان د خپل مُلک نه راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16692, 'Isaiah 7:19', 'Isaiah', 7, 19, '&nbsp;هغوئ ټول به راشى، د ژورو وادۍ باندې او په غارونو او ګټو باندې او د ازغو په هر يو بوټے او په ولاړو اوبو باندې به کښېنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16693, 'Isaiah 7:20', 'Isaiah', 7, 20, '&nbsp;کله چې هغه وخت راشى، نو مالِک خُدائ به د اسور بادشاه د نائى په توګه د فرات سيند د بلې غاړې نه راولى او هغه به ستاسو ږيرې، سر او په بدنونو وېښتۀ کل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16694, 'Isaiah 7:21', 'Isaiah', 7, 21, '&nbsp;په هغه وخت چې کوم يو کس سره يوه سخۍ او يو دوه ګډې چېلۍ پاتې وى نو هغه به خوش قسمته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16695, 'Isaiah 7:22', 'Isaiah', 7, 22, '&nbsp;دا به دومره زيات پئ ورکوى چې د هغۀ ضرورت به ښۀ پوره کوى. آو، چې په هغه مُلک کښې څوک هم ژوندى پاتې وى نو هغوئ به ملائى او شات خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16696, 'Isaiah 7:23', 'Isaiah', 7, 23, '&nbsp;کله چې هغه وخت راشى، نو د انګورو هغه ښۀ باغونه، چې په هر يو کښې يو زر د انګورو بوټى وى او د هر يو باغ قيمت د سپينو زرو يو زر سيکې وى، نو هغه به هم د ازغو او غنو نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16697, 'Isaiah 7:24', 'Isaiah', 7, 24, '&nbsp;خلق به هلته د غشو او ليندو سره د ښکار دپاره ځى. آو، هغه ټول مُلک به د ازغو او غنو نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16698, 'Isaiah 7:25', 'Isaiah', 7, 25, '&nbsp;په کومو غونډو باندې چې د فصلونو دپاره کوداله کېده نو هغه به هم د ازغو نه داسې ډک وى چې هيڅ څوک به هلته نۀ شى تلے. هغه به يو داسې ځائ جوړ شى چې چرته څاروى او ګډې څريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16699, 'Isaiah 8:1', 'Isaiah', 8, 1, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”د ليکلو دپاره يوه لويه تخته واخله او په هغې باندې صفا صفا دا وليکه چې، د تېزۍ مال غنيمت او زر زر لوټ مار.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16700, 'Isaiah 8:2', 'Isaiah', 8, 2, '&nbsp;ما د اورِياه اِمام او د يبرکياه زوئ زکرياه په وړاندې دا وليکل او دا دواړه کسان ايمانداره ګواهان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');